Office.onReady(() => {

  Office.actions.associate("sendToErp", sendToErp);

});

function sendToErp(event) {

  Office.context.mailbox.item.notificationMessages.replaceAsync(
    "send",
    {
      type: "informationalMessage",
      message: "COMMAND WORKS",
      persistent: false
    });

  event.completed();
}